-- ── HELPER: Get current user role from JWT or portal_users ──
CREATE OR REPLACE FUNCTION public.sbd_get_user_role()
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT role FROM public.sbd_portal_users WHERE auth_uid = auth.uid() LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.sbd_get_user_facility()
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT facility_id FROM public.sbd_portal_users WHERE auth_uid = auth.uid() LIMIT 1;
$$;

