RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER AS $$
  SELECT COALESCE(assigned_facility_ids, '{}') FROM public.sbd_portal_users WHERE auth_uid = auth.uid() LIMIT 1;
$$;

