-- ── ATOMIC ASSESSMENT RECORDING ──
-- Records an assessment, updates staff gates, auto-promotes if all 3 next-belt gates pass
CREATE OR REPLACE FUNCTION public.sbd_record_assessment_atomic(
  p_staff_id integer,
  p_type text,
  p_target_belt text,
  p_result text,
  p_notes text DEFAULT NULL,
  p_assessed_by uuid DEFAULT NULL,
  p_assessed_at date DEFAULT CURRENT_DATE
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_staff record;
  v_belt text;
  v_belt_idx int;
  v_target_idx int;
  v_promoted boolean := false;
  belt_order text[] := ARRAY['White','Yellow','Green','Blue','Brown','Black'];
BEGIN
  -- Validate inputs
  IF p_type NOT IN ('Competency','Simulation','Observation') THEN
    RAISE EXCEPTION 'Invalid assessment type: %', p_type;
  END IF;
  IF p_result NOT IN ('pass','fail') THEN
    RAISE EXCEPTION 'Invalid result: %', p_result;
  END IF;
  IF p_target_belt NOT IN ('White','Yellow','Green','Blue','Brown','Black') THEN
    RAISE EXCEPTION 'Invalid target belt: %', p_target_belt;
  END IF;

  -- Lock the staff row
  SELECT * INTO v_staff FROM public.sbd_staff WHERE id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Staff member not found: %', p_staff_id;
  END IF;

  v_belt := v_staff.belt;
  v_belt_idx := array_position(belt_order, v_belt);
  v_target_idx := array_position(belt_order, p_target_belt);

  -- Update current belt gates
  IF v_target_idx = v_belt_idx THEN
    IF p_type = 'Competency' THEN
      UPDATE public.sbd_staff SET cur_comp = p_result, updated_at = now() WHERE id = p_staff_id;
    ELSIF p_type = 'Simulation' THEN
      UPDATE public.sbd_staff SET cur_sim = p_result, updated_at = now() WHERE id = p_staff_id;
    ELSE
      UPDATE public.sbd_staff SET cur_obs = p_result, updated_at = now() WHERE id = p_staff_id;
    END IF;
  -- Update next belt gates
  ELSIF v_target_idx = v_belt_idx + 1 THEN
    IF p_type = 'Competency' THEN
      UPDATE public.sbd_staff SET nxt_comp = p_result, updated_at = now() WHERE id = p_staff_id;
    ELSIF p_type = 'Simulation' THEN
      UPDATE public.sbd_staff SET nxt_sim = p_result, updated_at = now() WHERE id = p_staff_id;
    ELSE
      UPDATE public.sbd_staff SET nxt_obs = p_result, updated_at = now() WHERE id = p_staff_id;
    END IF;
  END IF;

  -- Insert assessment history
  INSERT INTO public.sbd_assessment_history(staff_id, facility_id, assessment_type, target_belt, result, notes, assessed_by, assessed_at)
  VALUES (p_staff_id, v_staff.facility_id, p_type, p_target_belt, p_result, p_notes, p_assessed_by, p_assessed_at);

  -- Resolve matching queue items
  UPDATE public.sbd_assessment_queue
  SET status = p_result, updated_at = now()
  WHERE staff_id = p_staff_id
    AND assessment_type = p_type
    AND target_belt = p_target_belt
    AND status = 'pending';

  -- Auto-promote if all 3 next-belt gates are pass
  UPDATE public.sbd_staff SET
    belt = p_target_belt,
    cur_comp = nxt_comp, cur_sim = nxt_sim, cur_obs = nxt_obs,
    nxt_comp = NULL, nxt_sim = NULL, nxt_obs = NULL,
    belt_since = CURRENT_DATE,
    updated_at = now()
  WHERE id = p_staff_id
    AND nxt_comp = 'pass' AND nxt_sim = 'pass' AND nxt_obs = 'pass';

  IF FOUND THEN v_promoted := true; END IF;

  RETURN jsonb_build_object(
    'success', true,
    'staff_id', p_staff_id,
    'promoted', v_promoted,
    'new_belt', CASE WHEN v_promoted THEN p_target_belt ELSE v_belt END
  );
END;
$$;

-- ── APPROVE REGISTRATION ──
-- Creates facility, creates portal user, updates registration status
CREATE OR REPLACE FUNCTION public.sbd_approve_registration(
  p_registration_id uuid,
  p_facility_id text,
  p_reviewed_by uuid DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_reg record;
BEGIN
  SELECT * INTO v_reg FROM public.sbd_pending_registrations WHERE id = p_registration_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Registration not found';
  END IF;
  IF v_reg.status != 'pending' THEN
    RAISE EXCEPTION 'Registration already processed';
  END IF;

  -- Create facility
  INSERT INTO public.sbd_facilities(id, name, location, department, contact_name, contact_email, since)
  VALUES (
    p_facility_id,
    v_reg.facility_name,
    v_reg.location,
    v_reg.department,
    v_reg.contact_name,
    v_reg.contact_email,
    to_char(now(), 'Mon YYYY')
  );

  -- Create portal user for the facility
  INSERT INTO public.sbd_portal_users(email, role, name, title, facility_id, initials)
  VALUES (
    v_reg.contact_email,
    'hospital',
    v_reg.contact_name,
    'Dept. Manager',
    p_facility_id,
    upper(left(split_part(v_reg.contact_name, ' ', 1), 1) || left(split_part(v_reg.contact_name, ' ', 2), 1))
  );

  -- Mark registration approved
  UPDATE public.sbd_pending_registrations
  SET status = 'approved', reviewed_by = p_reviewed_by, reviewed_at = now()
  WHERE id = p_registration_id;

  RETURN jsonb_build_object('success', true, 'facility_id', p_facility_id);
END;
$$;

-- ── REJECT REGISTRATION ──
CREATE OR REPLACE FUNCTION public.sbd_reject_registration(
  p_registration_id uuid,
  p_reviewed_by uuid DEFAULT NULL
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  UPDATE public.sbd_pending_registrations
  SET status = 'rejected', reviewed_by = p_reviewed_by, reviewed_at = now()
  WHERE id = p_registration_id AND status = 'pending';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Registration not found or already processed';
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- ── NETWORK STATS AGGREGATION ──
-- Returns cross-facility belt distribution, green percentage, and more
CREATE OR REPLACE FUNCTION public.sbd_network_stats(p_facility_ids text[] DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE AS $$
DECLARE
  v_result jsonb;
  v_belt_dist jsonb;
  v_fac_stats jsonb;
BEGIN
  -- Belt distribution across all (or filtered) facilities
  SELECT jsonb_object_agg(belt, cnt) INTO v_belt_dist
  FROM (
    SELECT belt, count(*) as cnt
    FROM public.sbd_staff
    WHERE active = true
      AND (p_facility_ids IS NULL OR facility_id = ANY(p_facility_ids))
    GROUP BY belt
  ) sub;

  -- Per-facility summary
  SELECT jsonb_agg(row_to_json(sub)) INTO v_fac_stats
  FROM (
    SELECT
      s.facility_id,
      f.name as facility_name,
      count(*) as total_staff,
      count(*) FILTER (WHERE array_position(ARRAY['Green','Blue','Brown','Black'], s.belt) IS NOT NULL) as above_green,
      round(avg(CASE s.belt
        WHEN 'White' THEN 1 WHEN 'Yellow' THEN 2 WHEN 'Green' THEN 3
        WHEN 'Blue' THEN 4 WHEN 'Brown' THEN 5 WHEN 'Black' THEN 6
      END), 2) as avg_belt
    FROM public.sbd_staff s
    JOIN public.sbd_facilities f ON f.id = s.facility_id
    WHERE s.active = true
      AND (p_facility_ids IS NULL OR s.facility_id = ANY(p_facility_ids))
    GROUP BY s.facility_id, f.name
  ) sub;

  v_result := jsonb_build_object(
    'belt_distribution', COALESCE(v_belt_dist, '{}'),
    'facility_stats', COALESCE(v_fac_stats, '[]'),
    'generated_at', now()
  );

  RETURN v_result;
END;
$$;

-- ── BULK STAFF INSERT ──
-- Accepts a JSON array of staff objects and inserts them
CREATE OR REPLACE FUNCTION public.sbd_bulk_insert_staff(p_staff jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_inserted integer := 0;
  v_errors jsonb := '[]';
  v_row jsonb;
  v_idx integer := 0;
BEGIN
  FOR v_row IN SELECT * FROM jsonb_array_elements(p_staff)
  LOOP
    v_idx := v_idx + 1;
    BEGIN
      INSERT INTO public.sbd_staff(
        facility_id, first_name, last_name, role, belt, belt_since, stars,
        cur_comp, cur_sim, cur_obs, nxt_comp, nxt_sim, nxt_obs,
        ps_enrolled, ps_done, ps_track, ps_module, promo_recommended
      ) VALUES (
        v_row->>'facility_id',
        v_row->>'first_name',
        v_row->>'last_name',
        v_row->>'role',
        COALESCE(v_row->>'belt', 'White'),
        COALESCE((v_row->>'belt_since')::date, CURRENT_DATE),
        COALESCE((v_row->>'stars')::integer, 0),
        v_row->>'cur_comp', v_row->>'cur_sim', v_row->>'cur_obs',
        v_row->>'nxt_comp', v_row->>'nxt_sim', v_row->>'nxt_obs',
        COALESCE((v_row->>'ps_enrolled')::boolean, false),
        COALESCE((v_row->>'ps_done')::boolean, false),
        COALESCE(v_row->>'ps_track', ''),
        COALESCE(v_row->>'ps_module', ''),
        COALESCE((v_row->>'promo_recommended')::boolean, false)
      );
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || jsonb_build_object('row', v_idx, 'error', SQLERRM);
    END;
  END LOOP;

  RETURN jsonb_build_object('inserted', v_inserted, 'errors', v_errors);
END;
$$;

-- ── STAFF POINTS CALCULATION ──
-- Server-side points calculation matching the frontend engine
CREATE OR REPLACE FUNCTION public.sbd_calc_points(p_staff_id integer)
RETURNS integer LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE
  v_staff record;
  v_pts integer := 0;
  v_belt_idx integer;
  belt_order text[] := ARRAY['White','Yellow','Green','Blue','Brown','Black'];
  belt_points integer[] := ARRAY[100, 250, 500, 1000, 2000, 5000];
  i integer;
BEGIN
  SELECT * INTO v_staff FROM public.sbd_staff WHERE id = p_staff_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  v_belt_idx := array_position(belt_order, v_staff.belt);

  -- Belt points for all earned belts up to current
  FOR i IN 1..v_belt_idx LOOP
    v_pts := v_pts + belt_points[i];
  END LOOP;

  -- Gate points (current tier)
  IF v_staff.cur_comp = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.cur_sim = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.cur_obs = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.cur_comp = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.cur_sim = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.cur_obs = 'fail' THEN v_pts := v_pts - 10; END IF;

  -- Gate points (next tier)
  IF v_staff.nxt_comp = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.nxt_sim = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.nxt_obs = 'pass' THEN v_pts := v_pts + 50; END IF;
  IF v_staff.nxt_comp = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.nxt_sim = 'fail' THEN v_pts := v_pts - 10; END IF;
  IF v_staff.nxt_obs = 'fail' THEN v_pts := v_pts - 10; END IF;

  -- Star bonus
  v_pts := v_pts + (v_staff.stars * 25);

  -- Position school bonus
  IF v_staff.ps_done THEN v_pts := v_pts + 200;
  ELSIF v_staff.ps_enrolled THEN v_pts := v_pts + 50;
  END IF;

  RETURN GREATEST(v_pts, 0);
END;
$$;

-- ── UPDATED_AT TRIGGER ──
CREATE OR REPLACE FUNCTION public.sbd_set_updated_at()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

