-- 1. Password reset tokens table
CREATE TABLE IF NOT EXISTS public.sbd_password_resets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.sbd_portal_users(id) ON DELETE CASCADE,
  token text NOT NULL UNIQUE,
