CREATE POLICY service_manages_emails ON public.sbd_email_queue FOR ALL USING (true) WITH CHECK (true);

-- 3. Trigger: queue welcome email when registration is approved
CREATE OR REPLACE FUNCTION public.sbd_on_registration_approved()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status = 'pending') THEN
    INSERT INTO public.sbd_email_queue (recipient_email, recipient_name, template, subject, body_data)
    VALUES (
      NEW.contact_email,
      NEW.contact_name,
      'registration_approved',
      'Your SIPS Belt Intelligence Portal is Ready',
      jsonb_build_object(
        'facility_name', NEW.facility_name,
        'contact_name', NEW.contact_name,
        'contact_email', NEW.contact_email,
        'approved_at', now()
      )
    );
  END IF;
  IF NEW.status = 'denied' AND (OLD.status IS NULL OR OLD.status = 'pending') THEN
    INSERT INTO public.sbd_email_queue (recipient_email, recipient_name, template, subject, body_data)
    VALUES (
      NEW.contact_email,
      NEW.contact_name,
      'registration_denied',
      'SIPS Belt Intelligence Portal Registration Update',
      jsonb_build_object(
        'facility_name', NEW.facility_name,
        'contact_name', NEW.contact_name
      )
    );
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_registration_status ON public.sbd_pending_registrations;
CREATE TRIGGER trg_registration_status
  AFTER UPDATE OF status ON public.sbd_pending_registrations
  FOR EACH ROW EXECUTE FUNCTION public.sbd_on_registration_approved();

