    'SIPS Belt Intelligence Portal - Registration Received',
    jsonb_build_object(
      'facility_name', NEW.facility_name,
      'contact_name', NEW.contact_name,
      'submitted_at', now()
    )
  );
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_registration_submitted ON public.sbd_pending_registrations;
CREATE TRIGGER trg_registration_submitted
  AFTER INSERT ON public.sbd_pending_registrations
  FOR EACH ROW EXECUTE FUNCTION public.sbd_on_registration_submitted();

-- 5. Trigger: queue password reset email when token is created
CREATE OR REPLACE FUNCTION public.sbd_on_password_reset_created()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user record;
BEGIN
  SELECT email, name INTO v_user
  FROM public.sbd_portal_users WHERE id = NEW.user_id;

  INSERT INTO public.sbd_email_queue (recipient_email, recipient_name, template, subject, body_data)
  VALUES (
    v_user.email,
    v_user.name,
    'password_reset',
    'SIPS Belt Intelligence Portal - Password Reset',
    jsonb_build_object(
      'name', v_user.name,
      'email', v_user.email,
      'reset_token', NEW.token,
      'expires_at', NEW.expires_at
    )
  );
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_password_reset_created ON public.sbd_password_resets;
CREATE TRIGGER trg_password_reset_created
  AFTER INSERT ON public.sbd_password_resets
  FOR EACH ROW EXECUTE FUNCTION public.sbd_on_password_reset_created();

-- 6. Trigger: notify admins when new registration arrives
CREATE OR REPLACE FUNCTION public.sbd_notify_admins_new_registration()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_admin record;
BEGIN
  FOR v_admin IN
    SELECT email, name FROM public.sbd_portal_users
    WHERE role = 'master_admin' AND active = true
  LOOP
    INSERT INTO public.sbd_email_queue (recipient_email, recipient_name, template, subject, body_data)
    VALUES (
      v_admin.email,
      v_admin.name,
      'admin_new_registration',
      'New Facility Registration: ' || NEW.facility_name,
      jsonb_build_object(
        'admin_name', v_admin.name,
        'facility_name', NEW.facility_name,
        'contact_name', NEW.contact_name,
        'contact_email', NEW.contact_email,
        'location', NEW.location,
        'department', NEW.department,
        'submitted_at', now()
      )
    );
  END LOOP;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_notify_admins_registration ON public.sbd_pending_registrations;
CREATE TRIGGER trg_notify_admins_registration
  AFTER INSERT ON public.sbd_pending_registrations
  FOR EACH ROW EXECUTE FUNCTION public.sbd_notify_admins_new_registration();

