-- Community Posts
CREATE TABLE bb_posts (
  id TEXT PRIMARY KEY DEFAULT 'p_' || extract(epoch from now())::bigint || '_' || substr(md5(random()::text), 1, 6),
  author_name TEXT NOT NULL,
  author_email TEXT,
  title TEXT DEFAULT '',
  body TEXT NOT NULL,
  tag TEXT DEFAULT 'general',
  likes INT DEFAULT 0,
  replies INT DEFAULT 0,
  pinned BOOLEAN DEFAULT false,
  lvl INT DEFAULT 1,
  cat TEXT DEFAULT 'General Conversations',
  thumb TEXT DEFAULT '',
  color TEXT DEFAULT '#CCFF00',
  is_bb BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Calendar Events
CREATE TABLE bb_events (
  id TEXT PRIMARY KEY DEFAULT 'ev_' || extract(epoch from now())::bigint,
  title TEXT NOT NULL,
  event_date DATE NOT NULL,
  event_time TIME DEFAULT '12:00',
  duration INT DEFAULT 60,
  location TEXT DEFAULT '',
  description TEXT DEFAULT '',
  created_by TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- About Page Content (singleton row)
CREATE TABLE bb_about (
  id INT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  hero_url TEXT DEFAULT '',
  hero_type TEXT DEFAULT 'image',
  gallery JSONB DEFAULT '[]'::jsonb,
  description TEXT DEFAULT '',
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Lesson Overrides (admin edits to lessons)
CREATE TABLE bb_lesson_overrides (
  id SERIAL PRIMARY KEY,
  mod_id TEXT NOT NULL,
  lesson_id TEXT NOT NULL,
  title TEXT,
  description TEXT,
  yt_id TEXT,
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(mod_id, lesson_id)
);

-- Members (basic tracking, no auth)
CREATE TABLE bb_members (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL,
  points INT DEFAULT 0,
  is_bb BOOLEAN DEFAULT false,
  is_admin BOOLEAN DEFAULT false,
  last_seen TIMESTAMPTZ DEFAULT now(),
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Post Likes (track who liked what)
CREATE TABLE bb_post_likes (
  member_email TEXT NOT NULL,
  post_id TEXT NOT NULL REFERENCES bb_posts(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (member_email, post_id)
);

-- Lesson Progress
CREATE TABLE bb_progress (
  member_email TEXT NOT NULL,
  lesson_id TEXT NOT NULL,
  completed_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (member_email, lesson_id)
);

-- Quiz Results
CREATE TABLE bb_quiz_results (
  id SERIAL PRIMARY KEY,
  member_email TEXT NOT NULL,
  quiz_id TEXT NOT NULL,
  score INT DEFAULT 0,
  total INT DEFAULT 0,
  answers JSONB DEFAULT '[]'::jsonb,
  completed_at TIMESTAMPTZ DEFAULT now()
);

