-- SBD OS Security Hardening v3
-- 1. Drop the dangerous ANY reading policy for anon users
DROP POLICY IF EXISTS "anon_read_by_auth_uid" ON public.sbd_portal_users;

-- 2. Create a secure reading policy for anon users (only allow reading their OWN profile during registration/restore if they have the token)
-- Actually, anon should never read all. Let's redirect them to use auth.uid()
CREATE POLICY "anon_read_by_auth_uid" ON public.sbd_portal_users
FOR SELECT TO anon
USING (auth_uid = auth.uid());

-- 3. Harden the update policy for authenticated users
DROP POLICY IF EXISTS "authenticated_update_own_profile" ON public.sbd_portal_users;
CREATE POLICY "authenticated_update_own_profile" ON public.sbd_portal_users
FOR UPDATE TO authenticated
USING (auth_uid = auth.uid())
WITH CHECK (auth_uid = auth.uid());

-- 4. Standardize RLS and selective policies for all core tables
DO $$
DECLARE
    tbl text;
    tables_to_harden text[] := ARRAY[
        'sbd_facilities', 'sbd_staff', 'sbd_assessment_queue', 'sbd_schedule', 
        'sbd_attendance', 'sbd_promotions', 'sbd_free_agents', 
        'sbd_pending_registrations', 'sbd_facility_trends', 'sbd_report_audit_log', 
        'sbd_placement_log', 'sbd_hospital_systems'
    ];
BEGIN
    FOREACH tbl IN ARRAY tables_to_harden
    LOOP
        -- Enable RLS
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', tbl);

        -- Drop any existing wide-open policies (Cleanup)
        EXECUTE format('DROP POLICY IF EXISTS "allow_all" ON public.%I', tbl);

        -- Master Admin Full Access
        EXECUTE format('CREATE POLICY "master_admin_all" ON public.%I FOR ALL TO authenticated USING (sbd_get_user_role() = ''master_admin'') WITH CHECK (sbd_get_user_role() = ''master_admin'')', tbl);

        -- Basic Read Access for Authenticated Users (Staff/Admins)
        EXECUTE format('CREATE POLICY "auth_read_all" ON public.%I FOR SELECT TO authenticated USING (TRUE)', tbl);
    END LOOP;
END $$;

