-- 1. Helper functions to avoid infinite recursion
CREATE OR REPLACE FUNCTION public.get_user_role() RETURNS text AS $$
DECLARE
  u_role text;
BEGIN
  SELECT role INTO u_role FROM public.user_profiles WHERE id = auth.uid() LIMIT 1;
  RETURN u_role;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION public.get_user_fid() RETURNS uuid AS $$
DECLARE
  u_fid uuid;
BEGIN
  SELECT fid INTO u_fid FROM public.user_profiles WHERE id = auth.uid() LIMIT 1;
  RETURN u_fid;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

