-- 3. USER_PROFILES POLICIES
-- A user can see their own profile.
-- Facility Admins & Hospital can see profiles with their FID.
-- Master Admins, Staff Admins, System Admins can see all.
CREATE POLICY "user_profiles_select" ON public.user_profiles FOR SELECT USING (
  id = auth.uid() OR 
  public.get_user_role() IN ('master_admin', 'staff_admin', 'system_admin') OR
  (public.get_user_role() IN ('facility_admin', 'hospital') AND fid = public.get_user_fid())
);

-- Users can update their own profile. Master Admin and System Admin can update all.
CREATE POLICY "user_profiles_update" ON public.user_profiles FOR UPDATE USING (
  id = auth.uid() OR 
  public.get_user_role() IN ('master_admin', 'system_admin')
);

-- Only Master Admins and System Admins can insert/delete bypassing edge functions.
-- (Note: initial user_profile row might be created via Supabase Auth trigger or Edge function overriding RLS)
CREATE POLICY "user_profiles_insert" ON public.user_profiles FOR INSERT WITH CHECK (
  public.get_user_role() IN ('master_admin', 'system_admin')
);

CREATE POLICY "user_profiles_delete" ON public.user_profiles FOR DELETE USING (
  public.get_user_role() IN ('master_admin', 'system_admin')
);

