-- ============================================
-- UPGRADED: submit_quiz with auto-scoring for MC/TF
-- Also stores candidate_email on the attempt
-- ============================================
CREATE OR REPLACE FUNCTION aip_submit_quiz(
  p_attempt_id UUID,
  p_responses JSONB,
  p_candidate_email TEXT DEFAULT NULL,
  p_time_spent INTEGER DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_resp JSONB;
  v_qid UUID;
  v_ans TEXT;
  v_correct TEXT;
  v_qtype TEXT;
  v_is_correct BOOLEAN;
  v_correct_count INTEGER := 0;
  v_total INTEGER := 0;
  v_score DECIMAL(5,2);
  v_passed BOOLEAN;
  v_threshold INTEGER;
  v_level_id UUID;
  v_mode TEXT;
  v_results JSONB := '[]'::jsonb;
  v_cat TEXT;
  v_cat_stats JSONB := '{}'::jsonb;
BEGIN
  SELECT a.level_id, a.mode::TEXT, l.passing_threshold
  INTO v_level_id, v_mode, v_threshold
  FROM aip_assessment_attempts a
  JOIN aip_levels l ON l.id = a.level_id
  WHERE a.id = p_attempt_id;

  IF v_level_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Attempt not found');
  END IF;

  -- Update candidate email on attempt
  IF p_candidate_email IS NOT NULL THEN
    UPDATE aip_assessment_attempts SET candidate_email = p_candidate_email WHERE id = p_attempt_id;
  END IF;

  FOR v_resp IN SELECT jsonb_array_elements(p_responses)
  LOOP
    v_qid := (v_resp->>'question_id')::UUID;
    v_ans := v_resp->>'candidate_answer';
    v_total := v_total + 1;

    -- Get question type and correct answer
    SELECT q.question_type::TEXT, a.answer_text
    INTO v_qtype, v_correct
    FROM aip_questions q
    LEFT JOIN aip_answers a ON a.question_id = q.id AND a.sort_order = 0
      AND (a.answer_component = 'full_answer' OR a.answer_component = 'expected_response')
    WHERE q.id = v_qid;

    -- Auto-score where possible
    v_is_correct := NULL;
    IF v_qtype IN ('true_false') AND v_correct IS NOT NULL THEN
      v_is_correct := lower(trim(v_ans)) = lower(trim(v_correct));
      IF v_is_correct THEN v_correct_count := v_correct_count + 1; END IF;
    ELSIF v_qtype IN ('multiple_choice') THEN
      -- Check answer_options
      SELECT EXISTS(
        SELECT 1 FROM aip_answer_options
        WHERE question_id = v_qid AND is_correct = true
        AND lower(trim(option_text)) = lower(trim(v_ans))
      ) INTO v_is_correct;
      IF v_is_correct THEN v_correct_count := v_correct_count + 1; END IF;
    END IF;

    -- Save response
    INSERT INTO aip_question_responses (attempt_id, question_id, candidate_answer, is_correct, needs_manual_scoring)
    VALUES (p_attempt_id, v_qid, v_ans, v_is_correct, v_is_correct IS NULL);

    -- Track category stats
    SELECT content_category::TEXT INTO v_cat FROM aip_questions WHERE id = v_qid;
    IF v_cat IS NOT NULL THEN
      v_cat_stats := v_cat_stats || jsonb_build_object(v_cat,
        jsonb_build_object(
          'total', COALESCE((v_cat_stats->v_cat->>'total')::int, 0) + 1,
          'correct', COALESCE((v_cat_stats->v_cat->>'correct')::int, 0) + CASE WHEN v_is_correct THEN 1 ELSE 0 END
        )
      );
    END IF;

    -- Build result (include answer for practice mode)
    v_results := v_results || jsonb_build_object(
      'question_id', v_qid,
      'candidate_answer', v_ans,
      'correct_answer', CASE WHEN v_mode = 'practice_quiz' THEN v_correct ELSE NULL END,
      'is_correct', v_is_correct,
      'needs_manual_scoring', v_is_correct IS NULL
    );
  END LOOP;

  -- Calculate score
  v_score := CASE WHEN v_total > 0 THEN ROUND(v_correct_count::NUMERIC / v_total * 100, 1) ELSE 0 END;
  v_passed := v_score >= v_threshold;

  -- Update attempt
  UPDATE aip_assessment_attempts
  SET completed_at = now(),
      total_questions = v_total,
      correct_answers = v_correct_count,
      score_percentage = v_score,
      passed = v_passed,
      time_spent_seconds = p_time_spent,
      category_breakdown = v_cat_stats,
      candidate_email = COALESCE(p_candidate_email, candidate_email)
  WHERE id = p_attempt_id;

  RETURN jsonb_build_object(
    'attempt_id', p_attempt_id,
    'total_questions', v_total,
    'correct_answers', v_correct_count,
    'score_percentage', v_score,
    'passed', v_passed,
    'passing_threshold', v_threshold,
    'mode', v_mode,
    'show_answers', v_mode = 'practice_quiz',
    'results', CASE WHEN v_mode = 'practice_quiz' THEN v_results ELSE '[]'::jsonb END,
    'category_breakdown', v_cat_stats
  );
END;
$$;

