-- ============================================
-- NEW RPC: Weak spot quiz generator
-- Auto-generates quiz from weak categories
-- ============================================
CREATE OR REPLACE FUNCTION aip_generate_weak_spot_quiz(
  p_candidate_email TEXT,
  p_level_id UUID,
  p_count INTEGER DEFAULT 15
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_weak_cats TEXT[];
  v_attempt_id UUID;
  v_questions JSONB;
BEGIN
  -- Find weak categories (below 80%)
  SELECT array_agg(category) INTO v_weak_cats
  FROM (
    SELECT q.content_category::TEXT as category,
      ROUND(COUNT(*) FILTER (WHERE qr.is_correct = true)::NUMERIC / NULLIF(COUNT(*),0) * 100, 1) as accuracy
    FROM aip_question_responses qr
    JOIN aip_assessment_attempts a ON a.id = qr.attempt_id
    JOIN aip_questions q ON q.id = qr.question_id
    WHERE a.candidate_email = p_candidate_email
      AND a.level_id = p_level_id
      AND qr.is_correct IS NOT NULL
    GROUP BY q.content_category
    HAVING COUNT(*) >= 3
      AND ROUND(COUNT(*) FILTER (WHERE qr.is_correct = true)::NUMERIC / NULLIF(COUNT(*),0) * 100, 1) < 80
  ) weak;

  -- If no weak areas found, use hard questions
  IF v_weak_cats IS NULL OR array_length(v_weak_cats, 1) IS NULL THEN
    RETURN aip_generate_quiz(p_level_id, 'weak_spot', p_count, NULL, '{"easy":0,"medium":30,"hard":70}'::jsonb);
  END IF;

  -- Create attempt
  INSERT INTO aip_assessment_attempts (level_id, mode, total_questions, candidate_email,
    config)
  VALUES (p_level_id, 'weak_spot', p_count, p_candidate_email,
    jsonb_build_object('weak_categories', v_weak_cats))
  RETURNING id INTO v_attempt_id;

  -- Pull from weak categories
  SELECT jsonb_agg(jsonb_build_object(
    'id', q.id, 'question_number', q.question_number, 'question_text', q.question_text,
    'question_type', q.question_type::TEXT, 'content_category', q.content_category::TEXT,
    'difficulty', q.difficulty::TEXT, 'part', q.part::TEXT, 'tags', q.tags
  ) ORDER BY random())
  INTO v_questions
  FROM aip_questions q
  WHERE q.level_id = p_level_id
    AND q.is_active = true AND q.is_approved = true
    AND q.content_category::TEXT = ANY(v_weak_cats)
  LIMIT p_count;

  RETURN jsonb_build_object(
    'attempt_id', v_attempt_id,
    'mode', 'weak_spot',
    'weak_categories', v_weak_cats,
    'total_questions', COALESCE(jsonb_array_length(v_questions), 0),
    'questions', COALESCE(v_questions, '[]'::jsonb)
  );
END;
$$;

-- Fix submit_quiz to return answers via SECURITY DEFINER (bypasses RLS)
CREATE OR REPLACE FUNCTION aip_submit_quiz(
  p_attempt_id UUID,
  p_responses JSONB,
  p_candidate_email TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_response JSONB;
  v_qid UUID;
  v_ans TEXT;
  v_correct TEXT;
  v_fail TEXT;
  v_total INTEGER := 0;
  v_level_id UUID;
  v_results JSONB := '[]'::jsonb;
BEGIN
  SELECT level_id INTO v_level_id FROM aip_assessment_attempts WHERE id = p_attempt_id;
  IF v_level_id IS NULL THEN RETURN jsonb_build_object('error','Attempt not found'); END IF;

  -- Update candidate email on attempt
  IF p_candidate_email IS NOT NULL THEN
    UPDATE aip_assessment_attempts SET candidate_email = p_candidate_email WHERE id = p_attempt_id;
  END IF;

  FOR v_response IN SELECT jsonb_array_elements(p_responses)
  LOOP
    v_qid := (v_response->>'question_id')::UUID;
    v_ans := v_response->>'candidate_answer';
    v_total := v_total + 1;

    -- Get correct answer (expected_response or full_answer)
    SELECT answer_text INTO v_correct FROM aip_answers
    WHERE question_id = v_qid AND answer_component IN ('full_answer','expected_response')
    ORDER BY sort_order LIMIT 1;

    -- Get fail indicator if exists
    SELECT answer_text INTO v_fail FROM aip_answers
    WHERE question_id = v_qid AND answer_component = 'fail_indicator'
    ORDER BY sort_order LIMIT 1;

    INSERT INTO aip_question_responses (attempt_id, question_id, candidate_answer, is_correct, needs_manual_scoring)
    VALUES (p_attempt_id, v_qid, v_ans, NULL, true);

    v_results := v_results || jsonb_build_object(
      'question_id', v_qid,
      'candidate_answer', v_ans,
      'correct_answer', v_correct,
      'fail_indicator', v_fail
    );
  END LOOP;

  UPDATE aip_assessment_attempts
  SET completed_at = now(), total_questions = v_total, correct_answers = 0, score_percentage = 0, passed = NULL
  WHERE id = p_attempt_id;

  RETURN jsonb_build_object('attempt_id', p_attempt_id, 'total_questions', v_total, 'results', v_results);
END;
$$;

