-- RPC: Generate weak spot quiz
CREATE OR REPLACE FUNCTION aip_generate_weak_spot_quiz(
  p_candidate_email TEXT,
  p_level_id UUID DEFAULT NULL,
  p_count INTEGER DEFAULT 15
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_weak_cats TEXT[];
  v_attempt_id UUID;
  v_questions JSONB;
BEGIN
  -- Find categories below 80%
  SELECT array_agg(category) INTO v_weak_cats
  FROM (
    SELECT q.content_category::TEXT as category,
      ROUND(COUNT(*) FILTER (WHERE qr.is_correct = true)::NUMERIC / NULLIF(COUNT(*),0) * 100, 1) as acc
    FROM aip_question_responses qr
    JOIN aip_assessment_attempts a ON a.id = qr.attempt_id
    JOIN aip_questions q ON q.id = qr.question_id
    WHERE a.candidate_email = p_candidate_email
      AND (p_level_id IS NULL OR a.level_id = p_level_id)
      AND qr.is_correct IS NOT NULL
    GROUP BY q.content_category HAVING COUNT(*) >= 3
  ) sub WHERE acc < 80;

  -- If no weak areas, use hard questions
  IF v_weak_cats IS NULL OR array_length(v_weak_cats, 1) IS NULL THEN
    v_weak_cats := NULL;
  END IF;

  -- Create attempt
  INSERT INTO aip_assessment_attempts (level_id, mode, total_questions, candidate_email,
    config)
  VALUES (p_level_id, 'weak_spot', p_count, p_candidate_email,
    jsonb_build_object('weak_categories', v_weak_cats))
  RETURNING id INTO v_attempt_id;

  -- Select questions from weak categories (or hard if none)
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'question_number', question_number, 'question_text', question_text,
    'question_type', question_type::TEXT, 'content_category', content_category::TEXT,
    'difficulty', difficulty::TEXT, 'part', part::TEXT, 'tags', tags
  ) ORDER BY random())
  INTO v_questions
  FROM aip_questions
  WHERE is_active AND is_approved
    AND (p_level_id IS NULL OR level_id = p_level_id)
    AND (v_weak_cats IS NULL OR content_category::TEXT = ANY(v_weak_cats))
    AND (v_weak_cats IS NOT NULL OR difficulty = 'hard')
  LIMIT p_count;

  RETURN jsonb_build_object(
    'attempt_id', v_attempt_id, 'mode', 'weak_spot',
    'weak_categories', v_weak_cats,
    'total_questions', COALESCE(jsonb_array_length(v_questions), 0),
    'questions', COALESCE(v_questions, '[]'::jsonb)
  );
END;
$$;

