-- Admin login (email + password + PIN)
CREATE FUNCTION aip_admin_login(p_email TEXT, p_password TEXT, p_pin TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_admin aip_admin_users%ROWTYPE;
BEGIN
  SELECT * INTO v_admin FROM aip_admin_users WHERE email = lower(p_email) AND is_active = true;
  IF v_admin.id IS NULL THEN RETURN jsonb_build_object('error','Invalid credentials'); END IF;
  IF v_admin.password_hash != p_password THEN RETURN jsonb_build_object('error','Invalid credentials'); END IF;
  IF v_admin.pin != p_pin THEN RETURN jsonb_build_object('error','Invalid PIN'); END IF;
  UPDATE aip_admin_users SET last_login = now() WHERE id = v_admin.id;
  RETURN jsonb_build_object('success',true,'admin_id',v_admin.id,'email',v_admin.email,
    'name',COALESCE(v_admin.first_name,'')||' '||COALESCE(v_admin.last_name,''),'role',v_admin.role);
END; $$;

-- Candidate login (email + PIN)
CREATE FUNCTION aip_candidate_login(p_email TEXT, p_pin TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_cand aip_candidates%ROWTYPE; v_fac aip_facilities%ROWTYPE;
BEGIN
  SELECT * INTO v_cand FROM aip_candidates WHERE email = lower(p_email) AND pin = p_pin AND is_active = true;
  IF v_cand.id IS NULL THEN RETURN jsonb_build_object('error','Invalid email or PIN'); END IF;
  SELECT * INTO v_fac FROM aip_facilities WHERE id = v_cand.facility_id;
  RETURN jsonb_build_object('success',true,'candidate_id',v_cand.id,
    'name',v_cand.first_name||' '||v_cand.last_name,'email',v_cand.email,
    'facility_id',v_cand.facility_id,'facility_name',v_fac.name,
    'belt_level_id',v_cand.current_belt_level_id,
    'belt_level_name',(SELECT name FROM aip_levels WHERE id = v_cand.current_belt_level_id),
    'belt_level_code',(SELECT code FROM aip_levels WHERE id = v_cand.current_belt_level_id),
    'script_level_id',v_cand.current_script_level_id,
    'script_level_name',(SELECT name FROM aip_levels WHERE id = v_cand.current_script_level_id),
    'competency_level_id',v_cand.current_competency_level_id,
    'competency_level_name',(SELECT name FROM aip_levels WHERE id = v_cand.current_competency_level_id),
    'available_assessments',(
      SELECT jsonb_agg(jsonb_build_object('id',fa.id,'level',l.name,'type',fa.assessment_type,
        'questions',fa.question_count,'time_limit',fa.time_limit_seconds,'threshold',fa.passing_threshold))
      FROM aip_formal_assessments fa JOIN aip_levels l ON l.id = fa.level_id
      WHERE fa.candidate_id = v_cand.id AND fa.status = 'available'
        AND (fa.available_from IS NULL OR fa.available_from <= now())
        AND (fa.available_until IS NULL OR fa.available_until >= now())
    ));
END; $$;

-- Admin: get all facilities
CREATE FUNCTION aip_admin_get_facilities()
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN (SELECT jsonb_agg(jsonb_build_object(
    'id',f.id,'name',f.name,'code',f.code,'city',f.city,'state',f.state,
    'candidate_count',(SELECT COUNT(*) FROM aip_candidates c WHERE c.facility_id = f.id AND c.is_active),
    'assessor_count',(SELECT COUNT(*) FROM aip_assessors a WHERE a.facility_id = f.id AND a.is_active),
    'active_tests',(SELECT COUNT(*) FROM aip_proctored_sessions ps WHERE ps.facility_id = f.id AND ps.status = 'in_progress')
  ) ORDER BY f.name) FROM aip_facilities f WHERE f.is_active);
END; $$;

-- Admin: get candidates
CREATE FUNCTION aip_admin_get_candidates(p_facility_id UUID DEFAULT NULL)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN (SELECT jsonb_agg(jsonb_build_object(
    'id',c.id,'name',c.first_name||' '||c.last_name,'email',c.email,
    'facility',f.name,'facility_id',c.facility_id,
    'belt_level',(SELECT code FROM aip_levels WHERE id = c.current_belt_level_id),
    'belt_level_name',(SELECT name FROM aip_levels WHERE id = c.current_belt_level_id),
    'script_level',(SELECT code FROM aip_levels WHERE id = c.current_script_level_id),
    'competency_level',(SELECT code FROM aip_levels WHERE id = c.current_competency_level_id),
    'pending_requests',(SELECT COUNT(*) FROM aip_assessment_requests r WHERE r.candidate_id = c.id AND r.status = 'pending'),
    'completed_tests',(SELECT COUNT(*) FROM aip_proctored_sessions ps WHERE ps.candidate_id = c.id AND ps.status = 'completed')
  ) ORDER BY f.name, c.last_name)
  FROM aip_candidates c JOIN aip_facilities f ON f.id = c.facility_id
  WHERE c.is_active AND (p_facility_id IS NULL OR c.facility_id = p_facility_id));
END; $$;

-- Admin: get pending requests
CREATE FUNCTION aip_admin_get_requests()
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN (SELECT jsonb_agg(jsonb_build_object(
    'id',r.id,'candidate_name',c.first_name||' '||c.last_name,'candidate_email',c.email,
    'facility',(SELECT name FROM aip_facilities WHERE id = c.facility_id),
    'level',l.name,'level_code',l.code,'type',r.assessment_type,
    'requested_at',r.requested_at,'status',r.status
  ) ORDER BY r.requested_at)
  FROM aip_assessment_requests r
  JOIN aip_candidates c ON c.id = r.candidate_id
  JOIN aip_levels l ON l.id = r.level_id
  WHERE r.status = 'pending');
END; $$;

-- Candidate: request assessment
CREATE FUNCTION aip_candidate_request_assessment(p_candidate_id UUID, p_level_id UUID, p_type TEXT DEFAULT 'level_1_knowledge')
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  INSERT INTO aip_assessment_requests (candidate_id, level_id, assessment_type) VALUES (p_candidate_id, p_level_id, p_type);
  RETURN jsonb_build_object('success',true,'message','Assessment request submitted. Your administrator will review and schedule your exam.');
END; $$;

-- Admin: approve request
CREATE FUNCTION aip_admin_approve_request(p_request_id UUID, p_admin_id UUID, p_question_count INTEGER DEFAULT 50, p_time_limit INTEGER DEFAULT 3600, p_available_from TIMESTAMPTZ DEFAULT now(), p_available_until TIMESTAMPTZ DEFAULT NULL)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_req aip_assessment_requests%ROWTYPE; v_fa_id UUID;
BEGIN
  SELECT * INTO v_req FROM aip_assessment_requests WHERE id = p_request_id;
  IF v_req.id IS NULL THEN RETURN jsonb_build_object('error','Request not found'); END IF;
  UPDATE aip_assessment_requests SET status='approved',reviewed_by=p_admin_id,reviewed_at=now() WHERE id=p_request_id;
  INSERT INTO aip_formal_assessments (request_id,candidate_id,level_id,assessment_type,question_count,time_limit_seconds,available_from,available_until,created_by)
  VALUES (p_request_id,v_req.candidate_id,v_req.level_id,v_req.assessment_type,p_question_count,p_time_limit,p_available_from,p_available_until,p_admin_id)
  RETURNING id INTO v_fa_id;
  RETURN jsonb_build_object('success',true,'assessment_id',v_fa_id);
END; $$;

-- Start proctored session (dual-PIN)
CREATE FUNCTION aip_start_proctored_session(p_formal_assessment_id UUID, p_candidate_pin TEXT, p_assessor_email TEXT, p_assessor_pin TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_fa aip_formal_assessments%ROWTYPE; v_cand aip_candidates%ROWTYPE; v_assessor aip_assessors%ROWTYPE; v_session_id UUID; v_attempt_id UUID;
BEGIN
  SELECT * INTO v_fa FROM aip_formal_assessments WHERE id=p_formal_assessment_id AND status='available';
  IF v_fa.id IS NULL THEN RETURN jsonb_build_object('error','Assessment not available'); END IF;
  SELECT * INTO v_cand FROM aip_candidates WHERE id=v_fa.candidate_id;
  IF v_cand.pin!=p_candidate_pin THEN RETURN jsonb_build_object('error','Invalid candidate PIN'); END IF;
  SELECT * INTO v_assessor FROM aip_assessors WHERE email=lower(p_assessor_email) AND pin=p_assessor_pin AND facility_id=v_cand.facility_id AND is_active;
  IF v_assessor.id IS NULL THEN RETURN jsonb_build_object('error','Invalid assessor credentials'); END IF;
  INSERT INTO aip_assessment_attempts (candidate_email,level_id,mode,total_questions,config) VALUES (v_cand.email,v_fa.level_id,'timed_test',v_fa.question_count,jsonb_build_object('formal',true,'proctored',true)) RETURNING id INTO v_attempt_id;
  INSERT INTO aip_proctored_sessions (formal_assessment_id,candidate_id,candidate_pin_verified,assessor_id,assessor_pin_verified,facility_id,attempt_id) VALUES (p_formal_assessment_id,v_cand.id,true,v_assessor.id,true,v_cand.facility_id,v_attempt_id) RETURNING id INTO v_session_id;
  UPDATE aip_formal_assessments SET status='in_progress' WHERE id=p_formal_assessment_id;
  RETURN jsonb_build_object('success',true,'session_id',v_session_id,'attempt_id',v_attempt_id,
    'candidate_name',v_cand.first_name||' '||v_cand.last_name,'assessor_name',v_assessor.first_name||' '||v_assessor.last_name,
    'facility',(SELECT name FROM aip_facilities WHERE id=v_cand.facility_id),'level',(SELECT name FROM aip_levels WHERE id=v_fa.level_id));
END; $$;

-- Admin: set candidate level
CREATE FUNCTION aip_admin_set_candidate_level(p_candidate_id UUID, p_level_type TEXT, p_level_id UUID, p_admin_id UUID, p_reason TEXT DEFAULT NULL)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_old UUID;
BEGIN
  IF p_level_type='belt' THEN SELECT current_belt_level_id INTO v_old FROM aip_candidates WHERE id=p_candidate_id; UPDATE aip_candidates SET current_belt_level_id=p_level_id,updated_at=now() WHERE id=p_candidate_id;
  ELSIF p_level_type='script' THEN SELECT current_script_level_id INTO v_old FROM aip_candidates WHERE id=p_candidate_id; UPDATE aip_candidates SET current_script_level_id=p_level_id,updated_at=now() WHERE id=p_candidate_id;
  ELSIF p_level_type='competency' THEN SELECT current_competency_level_id INTO v_old FROM aip_candidates WHERE id=p_candidate_id; UPDATE aip_candidates SET current_competency_level_id=p_level_id,updated_at=now() WHERE id=p_candidate_id;
  END IF;
  INSERT INTO aip_candidate_level_history (candidate_id,level_type,from_level_id,to_level_id,changed_by,reason) VALUES (p_candidate_id,p_level_type,v_old,p_level_id,p_admin_id,p_reason);
  RETURN jsonb_build_object('success',true,'level_type',p_level_type,'new_level',(SELECT name FROM aip_levels WHERE id=p_level_id));
END; $$;

