-- Candidate login (email + PIN)
CREATE FUNCTION aip_candidate_login(p_email TEXT, p_pin TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v aip_candidates%ROWTYPE; f aip_facilities%ROWTYPE;
BEGIN
