    'knowledge_level_id',v.knowledge_level_id,
    'knowledge_level',(SELECT name FROM aip_levels WHERE id=v.knowledge_level_id),
    'script_level_id',v.script_level_id,
    'script_level',(SELECT name FROM aip_levels WHERE id=v.script_level_id),
    'practice_level_id',v.practice_level_id,
    'practice_level',(SELECT name FROM aip_levels WHERE id=v.practice_level_id),
    'overall_belt_id',v.overall_belt_id,
    'overall_belt',(SELECT name FROM aip_levels WHERE id=v.overall_belt_id),
    'available_assessments',(
      SELECT jsonb_agg(jsonb_build_object('id',fa.id,'level',l.name,'type',fa.assessment_type,
        'questions',fa.question_count,'time_limit',fa.time_limit_minutes,'threshold',fa.passing_threshold))
      FROM aip_formal_assessments fa JOIN aip_levels l ON l.id=fa.level_id
      WHERE fa.candidate_id=v.id AND fa.status='available'
        AND (fa.available_from IS NULL OR fa.available_from<=now())
        AND (fa.available_until IS NULL OR fa.available_until>=now())
    ));
END; $$;

-- Admin: get all facilities
CREATE FUNCTION aip_admin_get_facilities()
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN (SELECT jsonb_agg(jsonb_build_object(
    'id',f.id,'name',f.name,'code',f.facility_code,'location',f.location,
    'candidate_count',(SELECT COUNT(*) FROM aip_candidates c WHERE c.facility_id=f.id AND c.is_active),
    'assessor_count',(SELECT COUNT(*) FROM aip_assessors a WHERE a.facility_id=f.id AND a.is_active),
    'active_tests',(SELECT COUNT(*) FROM aip_proctored_sessions ps WHERE ps.facility_id=f.id AND ps.completed_at IS NULL)
  ) ORDER BY f.name) FROM aip_facilities f WHERE f.is_active);
END; $$;

-- Admin: get candidates
CREATE FUNCTION aip_admin_get_candidates(p_facility_id UUID DEFAULT NULL)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN (SELECT jsonb_agg(jsonb_build_object(
    'id',c.id,'name',c.first_name||' '||c.last_name,'email',c.email,
    'facility',f.name,'facility_id',c.facility_id,
    'knowledge_level',(SELECT code FROM aip_levels WHERE id=c.knowledge_level_id),
    'script_level',(SELECT code FROM aip_levels WHERE id=c.script_level_id),
    'practice_level',(SELECT code FROM aip_levels WHERE id=c.practice_level_id),
    'overall_belt',(SELECT code FROM aip_levels WHERE id=c.overall_belt_id),
    'pending_requests',(SELECT COUNT(*) FROM aip_assessment_requests r WHERE r.candidate_id=c.id AND r.status='pending'),
    'completed_tests',(SELECT COUNT(*) FROM aip_proctored_sessions ps WHERE ps.candidate_id=c.id AND ps.completed_at IS NOT NULL)
  ) ORDER BY f.name, c.last_name)
  FROM aip_candidates c JOIN aip_facilities f ON f.id=c.facility_id
  WHERE c.is_active AND (p_facility_id IS NULL OR c.facility_id=p_facility_id));
END; $$;

-- Start proctored session (dual-PIN)
CREATE FUNCTION aip_start_proctored_session(p_formal_assessment_id UUID, p_candidate_pin TEXT, p_assessor_email TEXT, p_assessor_pin TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_fa aip_formal_assessments%ROWTYPE; v_cand aip_candidates%ROWTYPE; v_ass aip_assessors%ROWTYPE; v_sid UUID; v_aid UUID;
BEGIN
  SELECT * INTO v_fa FROM aip_formal_assessments WHERE id=p_formal_assessment_id AND status='available';
  IF v_fa.id IS NULL THEN RETURN jsonb_build_object('error','Assessment not available'); END IF;
  SELECT * INTO v_cand FROM aip_candidates WHERE id=v_fa.candidate_id;
  IF v_cand.pin!=p_candidate_pin THEN RETURN jsonb_build_object('error','Invalid candidate PIN'); END IF;
  SELECT * INTO v_ass FROM aip_assessors WHERE email=lower(p_assessor_email) AND pin=p_assessor_pin AND facility_id=v_cand.facility_id AND is_active;
  IF v_ass.id IS NULL THEN RETURN jsonb_build_object('error','Invalid assessor credentials'); END IF;
  INSERT INTO aip_assessment_attempts (candidate_email,level_id,mode,total_questions,config) VALUES (v_cand.email,v_fa.level_id,'timed_test',v_fa.question_count,jsonb_build_object('formal',true,'proctored',true)) RETURNING id INTO v_aid;
  INSERT INTO aip_proctored_sessions (formal_assessment_id,candidate_id,candidate_pin_verified,assessor_id,assessor_pin_verified,facility_id,attempt_id) VALUES (p_formal_assessment_id,v_cand.id,true,v_ass.id,true,v_cand.facility_id,v_aid) RETURNING id INTO v_sid;
  UPDATE aip_formal_assessments SET status='in_progress' WHERE id=p_formal_assessment_id;
  RETURN jsonb_build_object('success',true,'session_id',v_sid,'attempt_id',v_aid,
    'candidate_name',v_cand.first_name||' '||v_cand.last_name,'assessor_name',v_ass.display_name,
    'facility',(SELECT name FROM aip_facilities WHERE id=v_cand.facility_id),
    'level',(SELECT name FROM aip_levels WHERE id=v_fa.level_id));
END; $$;

