-- RPC: Candidate self-register
CREATE OR REPLACE FUNCTION aip_candidate_register(
  p_email TEXT, p_first_name TEXT, p_last_name TEXT, p_facility_code TEXT, p_pin TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_fac aip_facilities%ROWTYPE; v_exists BOOLEAN;
BEGIN
  SELECT * INTO v_fac FROM aip_facilities WHERE facility_code = upper(p_facility_code) AND is_active;
  IF v_fac.id IS NULL THEN RETURN jsonb_build_object('error','Facility code not found. Contact your administrator.'); END IF;
  SELECT EXISTS(SELECT 1 FROM aip_candidates WHERE email = lower(p_email)) INTO v_exists;
  IF v_exists THEN RETURN jsonb_build_object('error','Email already registered.'); END IF;
  SELECT EXISTS(SELECT 1 FROM aip_registrations WHERE email = lower(p_email) AND status = 'pending') INTO v_exists;
  IF v_exists THEN RETURN jsonb_build_object('error','Registration already pending.'); END IF;
  INSERT INTO aip_registrations (email, first_name, last_name, facility_id, pin)
  VALUES (lower(p_email), p_first_name, p_last_name, v_fac.id, p_pin);
  RETURN jsonb_build_object('success',true,'message','Registration submitted. Your facility administrator will review your request.');
END; $$;

-- RPC: Facility admin approve registration (checks seat limit)
CREATE OR REPLACE FUNCTION aip_approve_registration(
  p_registration_id UUID, p_admin_id UUID, p_knowledge_level UUID DEFAULT NULL
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE v_reg aip_registrations%ROWTYPE; v_fac aip_facilities%ROWTYPE; v_count INTEGER;
BEGIN
  SELECT * INTO v_reg FROM aip_registrations WHERE id = p_registration_id AND status = 'pending';
  IF v_reg.id IS NULL THEN RETURN jsonb_build_object('error','Registration not found'); END IF;
  SELECT * INTO v_fac FROM aip_facilities WHERE id = v_reg.facility_id;
  SELECT COUNT(*) INTO v_count FROM aip_candidates WHERE facility_id = v_reg.facility_id AND is_active;
  IF v_count >= v_fac.max_candidates THEN
    RETURN jsonb_build_object('error','Seat limit reached ('||v_fac.max_candidates||' candidates). Request a seat increase from SIPS admin.');
  END IF;
  INSERT INTO aip_candidates (email, pin, first_name, last_name, facility_id, knowledge_level_id, script_level_id, practice_level_id, overall_belt_id, assigned_by)
  VALUES (v_reg.email, v_reg.pin, v_reg.first_name, v_reg.last_name, v_reg.facility_id,
    COALESCE(p_knowledge_level, 'a0000001-0000-0000-0000-000000000001'),
    'a0000001-0000-0000-0000-000000000001',
    COALESCE(p_knowledge_level, 'a0000001-0000-0000-0000-000000000001'),
    COALESCE(p_knowledge_level, 'a0000001-0000-0000-0000-000000000001'),
    p_admin_id);
  UPDATE aip_registrations SET status = 'approved', reviewed_by = p_admin_id, reviewed_at = now() WHERE id = p_registration_id;
  RETURN jsonb_build_object('success',true);
END; $$;

