-- GREEN additive: heartbeat presence + pin handshake for observations.

-- Permanent per-participant observation pin (unique to the person, stays for life).
alter table public.staff add column if not exists observation_pin text;

-- Heartbeat presence: stamped on every scoring action so the queue can derive
-- Active / Paused / Stalled without any realtime infrastructure.
alter table public.observations add column if not exists last_active_at timestamptz;

-- Pin handshake chain written at observation start. Candidate confirmed by their
-- own pin; observer bound by their pin with belt captured at that moment; any
-- above-belt override carries the authorizing upline, their belt, and a reason.
alter table public.observations add column if not exists handshake jsonb;

-- SIPS observer audit: a sampled review of a completed observation marking the
-- observer's conduct sound or not. Feeds the observer audit-success rate.
create table public.observation_audits (
  id              uuid primary key default gen_random_uuid(),
  observation_id  uuid not null references public.observations(id) on delete cascade,
  observer_id     uuid,
  observer_name   text,
  outcome         text not null check (outcome in ('sound','unsound')),
  notes           text,
  audited_by      uuid,
  audited_by_name text,
  audited_at      timestamptz default now()
);
create index idx_oa_observer on public.observation_audits(observer_id);
create index idx_oa_obs      on public.observation_audits(observation_id);
alter table public.observation_audits enable row level security;
