CREATE OR REPLACE FUNCTION public.get_user_fid()
 RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER
AS $function$
DECLARE u_fid uuid;
BEGIN
  SELECT facility_id INTO u_fid FROM public.sbd_portal_users WHERE auth_uid = auth.uid() LIMIT 1;
  RETURN u_fid;
END;
$function$;

